import { execSync } from 'node:child_process';
it('build completes in under 90 seconds', () => {
  const t0 = Date.now();
  execSync('npm run build', { stdio: 'ignore' });
  const elapsed = Date.now() - t0;
  expect(elapsed).toBeLessThan(90_000);
});
